    "s_1774026466261_94",  # qa 59KB
]

for sid in sessions:
    path = f".state/sessions/history/{sid}/session.jsonl"
    total_bytes = 0
    tool_result_bytes = 0
    read_calls = 0
    read_with_offset = 0
    bash_calls = 0
    bash_with_grep = 0
    bash_with_pipe = 0
    large_results = 0
    very_large = 0
    full_file_reads = []  # Track files read without offset

    try:
        with open(path) as f:
            for line in f:
                total_bytes += len(line)
                try:
                    msg = json.loads(line)
                except:
                    continue

                role = msg.get("role", "")

                if role == "toolResult":
                    content = msg.get("content", [])
                    result_text = ""
                    if isinstance(content, list):
                        for block in content:
                            if isinstance(block, dict):
                                result_text += block.get("text", "")
                    elif isinstance(content, str):
                        result_text = content
                    result_size = len(result_text)
                    tool_result_bytes += result_size
                    if result_size > 10000:
                        large_results += 1
                    if result_size > 20000:
                        very_large += 1

                if role == "assistant":
                    content = msg.get("content", [])
                    if isinstance(content, list):
                        for block in content:
                            if isinstance(block, dict) and block.get("type") == "toolCall":
                                name = block.get("name", "")
                                args_str = block.get("arguments", "{}")
                                try:
                                    args = json.loads(args_str) if isinstance(args_str, str) else args_str
                                except:
                                    args = {}

                                if name == "read":
                                    read_calls += 1
                                    if args.get("offset") or args.get("limit"):
                                        read_with_offset += 1
                                    else:
                                        fpath = args.get("path", "?")
                                        full_file_reads.append(fpath)
                                elif name == "bash":
                                    cmd = args.get("command", "")
                                    bash_calls += 1
                                    if "grep" in cmd or "rg " in cmd:
                                        bash_with_grep += 1
                                    if "|" in cmd:
                                        bash_with_pipe += 1

        pct = (tool_result_bytes / total_bytes * 100) if total_bytes > 0 else 0
        agent = json.load(open(f".state/sessions/history/{sid}/meta.json")).get("agent", "?")
        print(f"\n{sid} ({agent}, {total_bytes//1024}KB):")
        print(f"  Tool results: {tool_result_bytes//1024}KB ({pct:.0f}% of session)")
        print(f"  read() calls: {read_calls} (with offset/limit: {read_with_offset}, full-file: {read_calls - read_with_offset})")
        print(f"  bash calls: {bash_calls} (with grep/rg: {bash_with_grep}, with pipe: {bash_with_pipe})")
        print(f"  Large results (>10KB): {large_results}, Very large (>20KB): {very_large}")
        if full_file_reads:
            print(f"  Full-file reads: {full_file_reads[:8]}{'...' if len(full_file_reads) > 8 else ''}")
