# Let me also check: do agents who USE grep/offset produce smaller sessions?
python3 << 'PYEOF'
import json, os

results = []

for s in os.listdir(".state/sessions/history/"):
    path = f".state/sessions/history/{s}/session.jsonl"
    try:
        meta = json.load(open(f".state/sessions/history/{s}/meta.json"))
        agent = meta.get("agent", "?")
        size = os.path.getsize(path)

        total_reads = 0
        targeted_reads = 0
        grep_usage = 0

        with open(path) as f:
            for line in f:
                msg = json.loads(line)
                if msg.get("role") == "assistant":
                    content = msg.get("content", [])
                    if isinstance(content, list):
                        for block in content:
                            if isinstance(block, dict) and block.get("type") == "toolCall":
                                name = block.get("name", "")
                                args_str = block.get("arguments", "{}")
                                try:
                                    args = json.loads(args_str) if isinstance(args_str, str) else args_str
                                except:
                                    args = {}
                                if name == "read":
                                    total_reads += 1
                                    if args.get("offset") or args.get("limit"):
                                        targeted_reads += 1
                                elif name == "bash":
                                    cmd = args.get("command", "")
                                    if "grep" in cmd or "rg " in cmd:
                                        grep_usage += 1

        if total_reads > 0:
            pct_targeted = targeted_reads / total_reads * 100
        else:
            pct_targeted = 100  # no reads = no waste

        results.append((agent, s, size, total_reads, targeted_reads, grep_usage, pct_targeted))
    except:
        pass

# Group by targeted vs untargeted
targeted = [r for r in results if r[6] > 50 and r[3] > 2]
untargeted = [r for r in results if r[6] < 30 and r[3] > 2]

avg_targeted = sum(r[2] for r in targeted) / len(targeted) if targeted else 0
avg_untargeted = sum(r[2] for r in untargeted) / len(untargeted) if untargeted else 0

print(f"Sessions with >50% targeted reads (n={len(targeted)}): avg size = {avg_targeted//1024}KB")
print(f"Sessions with <30% targeted reads (n={len(untargeted)}): avg size = {avg_untargeted//1024}KB")
print(f"Difference: {(avg_untargeted - avg_targeted)//1024}KB ({(avg_untargeted/avg_targeted - 1)*100:.0f}% larger)")

